using UnityEngine;
using UnityEditor;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;

public class NoteFixer {
    public static void Fix() {
        Volume[] volumes = Object.FindObjectsOfType<Volume>();
        Volume globalVolume = null;
        foreach (var v in volumes) {
            if (v.isGlobal) { globalVolume = v; break; }
        }
        if (globalVolume == null) {
            GameObject go = new GameObject("Global Volume");
            globalVolume = go.AddComponent<Volume>();
            globalVolume.isGlobal = true;
        }

        if (globalVolume.profile == null) {
            globalVolume.profile = ScriptableObject.CreateInstance<VolumeProfile>();
            AssetDatabase.CreateAsset(globalVolume.profile, "Assets/Scenes/BasicScene/GlobalVolume Profile Auto.asset");
        }

        Bloom bloom;
        if (!globalVolume.profile.TryGet<Bloom>(out bloom)) {
            bloom = globalVolume.profile.Add<Bloom>(true);
        }
        bloom.active = true;
        bloom.intensity.Override(2.5f);
        bloom.threshold.Override(0.9f);
        bloom.scatter.Override(0.7f);

        var cameraData = Camera.main.GetComponent<UniversalAdditionalCameraData>();
        if (cameraData == null) {
            cameraData = Camera.main.gameObject.AddComponent<UniversalAdditionalCameraData>();
        }
        cameraData.renderPostProcessing = true;

        string prefabPath = "Assets/Prefabs/Note.prefab";
        GameObject notePrefab = AssetDatabase.LoadAssetAtPath<GameObject>(prefabPath);
        if (notePrefab != null) {
            Renderer[] renderers = notePrefab.GetComponentsInChildren<Renderer>(true);
            foreach (var r in renderers) {
                Material m = r.sharedMaterial;
                if (m == null || m.name == "Default-Material" || m.name == "Lit White" || m.name == "UniversalMaterialWhite") {
                    Material glowMat = new Material(Shader.Find("Universal Render Pipeline/Lit"));
                    glowMat.EnableKeyword("_EMISSION");
                    glowMat.globalIlluminationFlags = MaterialGlobalIlluminationFlags.RealtimeEmissive;
                    glowMat.SetColor("_EmissionColor", new Color(0f, 1f, 1f) * 3f);
                    glowMat.SetColor("_BaseColor", new Color(0.8f, 1f, 1f));

                    string matPath = "Assets/Materials/NoteGlow.mat";
                    if (!AssetDatabase.IsValidFolder("Assets/Materials")) {
                        AssetDatabase.CreateFolder("Assets", "Materials");
                    }
                    AssetDatabase.CreateAsset(glowMat, matPath);
                    r.sharedMaterial = AssetDatabase.LoadAssetAtPath<Material>(matPath);
                    EditorUtility.SetDirty(r);
                } else {
                    m.EnableKeyword("_EMISSION");
                    m.globalIlluminationFlags = MaterialGlobalIlluminationFlags.RealtimeEmissive;
                    if (m.GetColor("_EmissionColor").maxColorComponent < 1f) {
                        m.SetColor("_EmissionColor", new Color(0f, 1f, 1f) * 3f);
                    }
                    EditorUtility.SetDirty(m);
                }
            }
            EditorUtility.SetDirty(notePrefab);
            PrefabUtility.SavePrefabAsset(notePrefab);
        }

        UnityEditor.SceneManagement.EditorSceneManager.SaveOpenScenes();
    }
}
